//! Toolchain catalog: types, the tolerant parser, and selection helpers.
//!
//! The catalog file (`catalog/toolchains-v1.json`) is generated by the catalog
//! part of the release and describes what PHP, Node.js and Composer versions can
//! be installed. This module owns the Rust side of that contract:
//!
//! * the immutable domain types (`ToolId`, `Profile`, `Artifact`, ...);
//! * a parser that is tolerant in the specific way the contract requires — an
//!   entry for a tool, OS, architecture, profile or archive format this build
//!   does not know is skipped and logged, and an artifact without a verifiable
//!   SHA-256 or with a non-HTTPS URL is dropped on its own. A single bad entry
//!   never fails the whole file;
//! * selection: pick the artifact for the running platform and profile, and
//!   resolve a user version spec (`php 8`, `8.4`, `8.4.15`, `latest`) to exactly
//!   one catalog version.
//!
//! The format is stable and documented in `docs/dev/toolchains-catalog.md`.

use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};

use crate::platform::{Arch, Os};

use super::consts::CATALOG_SCHEMA_VERSION;

mod load;
mod resolve;

pub use load::{
    BUNDLED_CATALOG_JSON, CatalogState, CatalogStatus, bundled_or_empty, catalog_ttl, load_bundled,
    load_or_bundled, parse_with_skips, read_cache, refresh, write_cache,
};
pub use resolve::{VersionSpec, resolve_version, resolve_version_for_platform};

/// The three tools the Toolchains release manages.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum ToolId {
    /// The PHP interpreter.
    Php,
    /// The Node.js runtime (and its bundled `npm`/`npx`).
    Node,
    /// The Composer dependency manager (a PHAR run by the active PHP).
    Composer,
}

impl ToolId {
    /// Lowercase identifier used in the catalog and on disk.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Php => "php",
            Self::Node => "node",
            Self::Composer => "composer",
        }
    }

    /// Every tool, in catalog order.
    pub const fn all() -> [ToolId; 3] {
        [Self::Php, Self::Node, Self::Composer]
    }

    /// Executables this tool provides through a shim, in `expected_binaries`
    /// order relative to the install root.
    ///
    /// Derived from the tool alone so the install validation and the shim
    /// generator agree, and so tests never spell a literal `php`/`php.exe`
    /// (v0.2.0 lesson).
    pub fn shims(self) -> &'static [&'static str] {
        match self {
            Self::Php => &["php"],
            Self::Node => &["node", "npm", "npx"],
            Self::Composer => &["composer"],
        }
    }

    /// Expected executables relative to the install root, derived from the real
    /// upstream archive layouts:
    ///
    /// * PHP Linux (`static-php-cli`) and PHP Windows (`windows.php.net`) unpack
    ///   `php` / `php.exe` directly at the install root;
    /// * Node Linux unpacks `bin/node`, `bin/npm`, `bin/npx` (after stripping
    ///   `node-vX-linux-x64/`); Node Windows unpacks `node.exe`, `npm.cmd`,
    ///   `npx.cmd` at the install root (after stripping `node-vX-win-x64/`);
    /// * Composer is a single `composer.phar` at the install root.
    pub fn primary_binary_paths(self, os: Os) -> Vec<String> {
        match (self, os) {
            (Self::Php, Os::Windows) => vec![executable_name("php", os)],
            (Self::Php, _) => vec![executable_name("php", os)],
            (Self::Node, Os::Windows) => vec![
                "node.exe".to_owned(),
                "npm.cmd".to_owned(),
                "npx.cmd".to_owned(),
            ],
            (Self::Node, _) => vec![
                "bin/node".to_owned(),
                "bin/npm".to_owned(),
                "bin/npx".to_owned(),
            ],
            (Self::Composer, _) => vec![php_phar_file().to_owned()],
        }
    }

    /// The primary executable path relative to the install root (for `which`).
    pub fn primary_binary_path(self, os: Os) -> String {
        match (self, os) {
            (Self::Php, _) => executable_name("php", os),
            (Self::Node, Os::Windows) => "node.exe".to_owned(),
            (Self::Node, _) => "bin/node".to_owned(),
            (Self::Composer, _) => php_phar_file().to_owned(),
        }
    }
}

impl fmt::Display for ToolId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl FromStr for ToolId {
    type Err = crate::DblError;

    fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
        match value.trim().to_ascii_lowercase().as_str() {
            "php" => Ok(Self::Php),
            "node" | "nodejs" => Ok(Self::Node),
            "composer" => Ok(Self::Composer),
            other => Err(crate::DblError::InvalidInput {
                field: "tool",
                reason: format!("unknown tool: {other} (expected php, node or composer)"),
            }),
        }
    }
}

/// Extension profile of a PHP build.
///
/// Linux PHP comes in two flavours with different extension sets; Node and
/// Composer have no profile. A `None` profile is the only value allowed for those
/// tools, and the only value produced for a Windows PHP build.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Profile {
    /// Default: Composer/Laravel basics, no intl/sodium/opcache.
    Common,
    /// Adds intl, sodium, opcache and mysqli; drops pdo_pgsql/pdo_sqlite.
    Bulk,
}

impl Profile {
    /// Identifier used in the catalog JSON and in the install directory suffix.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Common => "common",
            Self::Bulk => "bulk",
        }
    }
}

impl fmt::Display for Profile {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl FromStr for Profile {
    type Err = crate::DblError;

    fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
        match value {
            "common" => Ok(Self::Common),
            "bulk" => Ok(Self::Bulk),
            other => Err(crate::DblError::InvalidInput {
                field: "profile",
                reason: format!("unknown profile: {other} (expected common or bulk)"),
            }),
        }
    }
}

/// Archive format of a toolchain artifact.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Format {
    /// `.tar.gz`.
    TarGz,
    /// `.zip`.
    Zip,
    /// A PHP PHAR (a plain file, copied into place).
    Phar,
}

impl Format {
    /// Identifier used in the catalog JSON.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::TarGz => "tar.gz",
            Self::Zip => "zip",
            Self::Phar => "phar",
        }
    }
}

impl FromStr for Format {
    type Err = crate::DblError;

    fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
        match value {
            "tar.gz" => Ok(Self::TarGz),
            "zip" => Ok(Self::Zip),
            "phar" => Ok(Self::Phar),
            other => Err(crate::DblError::InvalidInput {
                field: "format",
                reason: format!("unknown archive format: {other}"),
            }),
        }
    }
}

/// Where an artifact's SHA-256 came from, so the trust story is explicit.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum HashOrigin {
    /// The upstream project publishes a checksum we copied.
    Upstream,
    /// No upstream checksum exists; the catalog generator pinned the hash of the
    /// exact bytes it downloaded once.
    Pinned,
}

impl HashOrigin {
    /// Identifier used in the catalog JSON.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Upstream => "upstream",
            Self::Pinned => "pinned",
        }
    }
}

impl FromStr for HashOrigin {
    type Err = crate::DblError;

    fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
        match value {
            "upstream" => Ok(Self::Upstream),
            "pinned" => Ok(Self::Pinned),
            other => Err(crate::DblError::InvalidInput {
                field: "hash_origin",
                reason: format!("unknown hash origin: {other}"),
            }),
        }
    }
}

/// One downloadable build of a tool for one platform and profile.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Artifact {
    os: ArtifactOs,
    arch: ArtifactArch,
    profile: Option<Profile>,
    format: Format,
    url: String,
    sha256: String,
    size_bytes: u64,
    source: String,
    hash_origin: HashOrigin,
    extensions: Vec<String>,
}

/// The `os` field of an artifact: a concrete OS, or `any` for a platform-neutral
/// artifact (Composer's PHAR).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ArtifactOs {
    /// Linux.
    Linux,
    /// Windows.
    Windows,
    /// Runs anywhere (only used by Composer).
    Any,
}

impl ArtifactOs {
    /// Identifier used in the catalog JSON.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Linux => "linux",
            Self::Windows => "windows",
            Self::Any => "any",
        }
    }
}

impl FromStr for ArtifactOs {
    type Err = crate::DblError;

    fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
        match value {
            "linux" => Ok(Self::Linux),
            "windows" => Ok(Self::Windows),
            "any" => Ok(Self::Any),
            other => Err(crate::DblError::InvalidInput {
                field: "os",
                reason: format!("unknown os: {other}"),
            }),
        }
    }
}

/// The `arch` field of an artifact: a concrete architecture, or `any` for a
/// platform-neutral artifact (Composer's PHAR).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ArtifactArch {
    /// 64-bit x86.
    X86_64,
    /// 64-bit ARM.
    Aarch64,
    /// Runs on any architecture (only used by Composer).
    Any,
}

impl ArtifactArch {
    /// Identifier used in the catalog JSON.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::X86_64 => "x86_64",
            Self::Aarch64 => "aarch64",
            Self::Any => "any",
        }
    }

    /// Whether this artifact architecture matches `arch`.
    pub fn matches(self, arch: Arch) -> bool {
        match self {
            Self::Any => true,
            Self::X86_64 => arch == Arch::X86_64,
            Self::Aarch64 => arch == Arch::Aarch64,
        }
    }
}

impl FromStr for ArtifactArch {
    type Err = crate::DblError;

    fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
        match value {
            "x86_64" => Ok(Self::X86_64),
            "aarch64" => Ok(Self::Aarch64),
            "any" => Ok(Self::Any),
            other => Err(crate::DblError::InvalidInput {
                field: "arch",
                reason: format!("unknown arch: {other}"),
            }),
        }
    }
}

impl Artifact {
    /// Builds an artifact, rejecting anything uninstallable.
    ///
    /// A SHA-256 must be 64 lowercase hex characters and the URL must be
    /// absolute HTTPS (AGENTS.md invariants 3 and 6). A size of zero is refused:
    /// it cannot be downloaded or space-checked.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        os: ArtifactOs,
        arch: ArtifactArch,
        profile: Option<Profile>,
        format: Format,
        url: impl Into<String>,
        sha256: impl Into<String>,
        size_bytes: u64,
        source: impl Into<String>,
        hash_origin: HashOrigin,
        extensions: Vec<String>,
    ) -> crate::Result<Self> {
        Self::new_with_policy(
            os,
            arch,
            profile,
            format,
            url,
            sha256,
            size_bytes,
            source,
            hash_origin,
            extensions,
            false,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn new_with_policy(
        os: ArtifactOs,
        arch: ArtifactArch,
        profile: Option<Profile>,
        format: Format,
        url: impl Into<String>,
        sha256: impl Into<String>,
        size_bytes: u64,
        source: impl Into<String>,
        hash_origin: HashOrigin,
        extensions: Vec<String>,
        allow_loopback_http: bool,
    ) -> crate::Result<Self> {
        let sha256 = sha256.into();
        if !is_sha256_hex(&sha256) {
            return Err(crate::DblError::InvalidInput {
                field: "sha256",
                reason: "must be 64 lowercase hex characters".to_owned(),
            });
        }
        let url = url.into();
        if !is_allowed_artifact_url(&url, allow_loopback_http) {
            return Err(crate::DblError::InvalidInput {
                field: "url",
                reason: "must be an absolute https URL".to_owned(),
            });
        }
        if size_bytes == 0 {
            return Err(crate::DblError::InvalidInput {
                field: "size_bytes",
                reason: "must be greater than zero".to_owned(),
            });
        }
        Ok(Self {
            os,
            arch,
            profile,
            format,
            url,
            sha256,
            size_bytes,
            source: source.into(),
            hash_origin,
            extensions,
        })
    }

    /// Target OS (or `any`).
    pub const fn os(&self) -> ArtifactOs {
        self.os
    }
    /// Target architecture (or `any`).
    pub const fn arch(&self) -> ArtifactArch {
        self.arch
    }
    /// Extension profile, or `None` for a profile-less build.
    pub const fn profile(&self) -> Option<Profile> {
        self.profile
    }
    /// Archive/format.
    pub const fn format(&self) -> Format {
        self.format
    }
    /// Download URL.
    pub fn url(&self) -> &str {
        &self.url
    }
    /// Expected lowercase-hex SHA-256.
    pub fn sha256(&self) -> &str {
        &self.sha256
    }
    /// Expected size in bytes.
    pub const fn size_bytes(&self) -> u64 {
        self.size_bytes
    }
    /// Upstream project name.
    pub fn source(&self) -> &str {
        &self.source
    }
    /// Where the hash came from.
    pub const fn hash_origin(&self) -> HashOrigin {
        self.hash_origin
    }
    /// PHP extensions this build includes, sorted. Empty for non-PHP tools.
    pub fn extensions(&self) -> &[String] {
        &self.extensions
    }

    /// Whether this artifact can be installed on `os`.
    pub fn matches_os(&self, os: Os) -> bool {
        match self.os {
            ArtifactOs::Any => true,
            ArtifactOs::Linux => os == Os::Linux,
            ArtifactOs::Windows => os == Os::Windows,
        }
    }

    /// Whether this artifact can be installed on `arch`.
    pub fn matches_arch(&self, arch: Arch) -> bool {
        self.arch.matches(arch)
    }

    /// Returns a copy with a different URL, for tests that serve a fixture over
    /// loopback HTTP. Only compiled in test builds, so the HTTPS invariant on
    /// [`Artifact::new`] still holds for production code.
    #[cfg(test)]
    pub fn with_url_for_test(mut self, url: impl Into<String>) -> Self {
        self.url = url.into();
        self
    }
}

/// One released version of a tool, with the artifacts that provide it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ToolVersion {
    version: String,
    series: String,
    lts: Option<bool>,
    artifacts: Vec<Artifact>,
}

impl ToolVersion {
    /// Builds a version from its parts (artifacts in catalog order).
    pub fn new(
        version: impl Into<String>,
        series: impl Into<String>,
        lts: Option<bool>,
        artifacts: Vec<Artifact>,
    ) -> Self {
        Self {
            version: version.into(),
            series: series.into(),
            lts,
            artifacts,
        }
    }

    /// Full version tag, e.g. `8.4.15` or `24.11.0`.
    pub fn version(&self) -> &str {
        &self.version
    }

    /// Release series, e.g. `8.4` or `24`.
    pub fn series(&self) -> &str {
        &self.series
    }

    /// Node LTS marker, `None` for non-Node tools.
    pub const fn lts(&self) -> Option<bool> {
        self.lts
    }

    /// Every artifact of this version.
    pub fn artifacts(&self) -> &[Artifact] {
        &self.artifacts
    }

    /// The best artifact for the running platform and requested profile.
    ///
    /// Preference: an exact `os`/`arch` match over `any`. For PHP the profile
    /// must match; for Node/Composer (no profile) any profile-less artifact
    /// qualifies.
    pub fn select_artifact(
        &self,
        os: Os,
        arch: Arch,
        profile: Option<Profile>,
    ) -> crate::Result<&Artifact> {
        // Exact platform `(os, arch)` first, then fallback to `any` matches.
        let mut any_match: Option<&Artifact> = None;
        for artifact in &self.artifacts {
            if !artifact.matches_os(os) || !artifact.matches_arch(arch) {
                continue;
            }
            if artifact.profile() != profile {
                continue;
            }
            if artifact.os() != ArtifactOs::Any && artifact.arch() != ArtifactArch::Any {
                return Ok(artifact);
            }
            any_match.get_or_insert(artifact);
        }
        if let Some(artifact) = any_match {
            return Ok(artifact);
        }
        Err(crate::DblError::Unsupported {
            reason: format!(
                "{} is not available on {os}-{arch}{}",
                self.version,
                profile
                    .map(|p| format!(" with the {} profile", p.as_str()))
                    .unwrap_or_default()
            ),
        })
    }
}

/// Every version of one tool, newest first.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ToolEntry {
    id: ToolId,
    versions: Vec<ToolVersion>,
}

impl ToolEntry {
    /// Builds an entry from its tool id and versions (newest first).
    pub fn new(id: ToolId, versions: Vec<ToolVersion>) -> Self {
        Self { id, versions }
    }

    /// The tool this entry describes.
    pub const fn id(&self) -> ToolId {
        self.id
    }

    /// Versions, newest first.
    pub fn versions(&self) -> &[ToolVersion] {
        &self.versions
    }
}

/// A parsed, validated toolchain catalog.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ToolchainCatalog {
    generated_at: String,
    source_url: String,
    tools: Vec<ToolEntry>,
}

impl ToolchainCatalog {
    /// Builds a catalog from entries (tools in catalog order).
    pub fn new(generated_at: impl Into<String>, source_url: impl Into<String>, tools: Vec<ToolEntry>) -> Self {
        Self {
            generated_at: generated_at.into(),
            source_url: source_url.into(),
            tools,
        }
    }

    /// An empty catalog, used when the generated file is not present yet.
    pub fn empty() -> Self {
        Self {
            generated_at: String::new(),
            source_url: String::new(),
            tools: Vec::new(),
        }
    }

    /// The `generated_at` stamp of the document.
    pub fn generated_at(&self) -> &str {
        &self.generated_at
    }

    /// The refresh source URL (may be empty for a hand-written fixture).
    pub fn source_url(&self) -> &str {
        &self.source_url
    }

    /// Every tool entry.
    pub fn tools(&self) -> &[ToolEntry] {
        &self.tools
    }

    /// The entry for `id`, if present.
    pub fn tool(&self, id: ToolId) -> Option<&ToolEntry> {
        self.tools.iter().find(|entry| entry.id() == id)
    }

    /// Every version of `id`, newest first (empty when the tool is absent).
    pub fn versions(&self, id: ToolId) -> &[ToolVersion] {
        self.tool(id).map(ToolEntry::versions).unwrap_or(&[])
    }
}

// ---------------------------------------------------------------------------
// Derivation helpers shared by install/shim code
// ---------------------------------------------------------------------------

/// File name of the Composer PHAR inside an install root.
pub const fn php_phar_file() -> &'static str {
    "composer.phar"
}

/// Appends the platform executable extension to `stem`.
///
/// Linux takes the bare name; Windows appends `.exe`. Tests derive expected file
/// names through this so a Windows build is not "passing" against a Linux name.
pub fn executable_name(stem: &str, os: Os) -> String {
    match os {
        Os::Windows => format!("{stem}.exe"),
        _ => stem.to_owned(),
    }
}

fn is_sha256_hex(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
}

fn is_https_url(value: &str) -> bool {
    let Some((scheme, rest)) = value.split_once("://") else {
        return false;
    };
    scheme == "https" && !rest.is_empty() && !rest.contains(char::is_whitespace)
}

pub(crate) fn is_loopback_http_url(value: &str) -> bool {
    let Ok(parsed) = reqwest::Url::parse(value) else {
        return false;
    };
    if parsed.scheme() != "http" {
        return false;
    }
    match parsed.host() {
        Some(url::Host::Domain(host)) => host.eq_ignore_ascii_case("localhost"),
        Some(url::Host::Ipv4(ip)) => ip.is_loopback(),
        Some(url::Host::Ipv6(ip)) => ip.is_loopback(),
        None => false,
    }
}

fn is_allowed_artifact_url(value: &str, allow_loopback_http: bool) -> bool {
    if is_https_url(value) {
        return true;
    }
    #[cfg(any(test, debug_assertions))]
    if allow_loopback_http && is_loopback_http_url(value) {
        return true;
    }
    let _ = allow_loopback_http;
    false
}

/// Whether debug-only loopback HTTP is enabled via environment variable.
/// Release builds always return `false`.
pub(crate) fn env_allows_loopback_http() -> bool {
    #[cfg(debug_assertions)]
    {
        std::env::var(super::consts::ENV_ALLOW_LOOPBACK_HTTP)
            .map(|v| matches!(v.trim(), "1" | "true" | "TRUE"))
            .unwrap_or(false)
    }
    #[cfg(not(debug_assertions))]
    {
        false
    }
}

