/// How many entries the tolerant parser skipped, per reason.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct SkipCounts {
    /// Tools with an unknown or missing id.
    pub tools: usize,
    /// Versions with an unusable version tag.
    pub versions: usize,
    /// Artifacts for an unknown OS/arch/profile/format.
    pub artifacts: usize,
}

impl SkipCounts {
    /// Total entries skipped.
    pub const fn total(&self) -> usize {
        self.tools + self.versions + self.artifacts
    }
}

/// Parses a catalog document tolerantly.
///
/// A bad schema version is the only whole-file error: a higher version may carry
/// semantics this build does not know, so reading it as if it were version 1 would
/// be wrong. Everything else degrades entry by entry — an unknown tool, an unknown
/// OS/arch/profile/format, or an artifact that fails validation is dropped with a
/// `tracing::debug!` line, and the rest of the file loads.
pub fn parse_catalog(text: &str) -> crate::Result<(ToolchainCatalog, SkipCounts)> {
    parse_catalog_inner(text, env_allows_loopback_http())
}

/// Parses a catalog allowing loopback HTTP URLs (debug/test builds only).
#[cfg(any(test, debug_assertions))]
pub fn parse_catalog_allow_loopback(text: &str) -> crate::Result<(ToolchainCatalog, SkipCounts)> {
    parse_catalog_inner(text, true)
}

fn parse_catalog_inner(
    text: &str,
    allow_loopback_http: bool,
) -> crate::Result<(ToolchainCatalog, SkipCounts)> {
    let document: WireDocument = serde_json::from_str(text).map_err(|err| {
        crate::DblError::Storage {
            reason: format!("toolchain catalog is not valid JSON: {err}"),
        }
    })?;
    if document.schema != CATALOG_SCHEMA_VERSION {
        return Err(crate::DblError::Unsupported {
            reason: format!(
                "toolchain catalog schema {} is not supported (this build reads schema {CATALOG_SCHEMA_VERSION})",
                document.schema
            ),
        });
    }

    let mut skips = SkipCounts::default();
    let mut tools: Vec<ToolEntry> = Vec::new();

    for wire_tool in document.tools {
        let Ok(id) = ToolId::from_str(&wire_tool.id) else {
            tracing::debug!(tool = %wire_tool.id, "toolchain catalog: skipping unknown tool");
            skips.tools += 1;
            continue;
        };
        let mut versions: Vec<ToolVersion> = Vec::new();
        for wire_version in wire_tool.versions {
            let version = wire_version.version.trim();
            if !is_version_tag(version) {
                tracing::debug!(tool = %id, version = %wire_version.version, "toolchain catalog: skipping unusable version");
                skips.versions += 1;
                continue;
            }
            let series = if wire_version.series.trim().is_empty() {
                default_series(id, version)
            } else {
                wire_version.series.trim().to_owned()
            };
            let mut artifacts: Vec<Artifact> = Vec::new();
            for wire_artifact in wire_version.artifacts {
                match convert_artifact(id, &wire_artifact, allow_loopback_http) {
                    Ok(artifact) => artifacts.push(artifact),
                    Err(reason) => {
                        tracing::debug!(
                            tool = %id,
                            version = %version,
                            url = %wire_artifact.url,
                            %reason,
                            "toolchain catalog: dropping artifact"
                        );
                        skips.artifacts += 1;
                    }
                }
            }
            if artifacts.is_empty() {
                // A version with no installable artifact is not offered.
                tracing::debug!(tool = %id, version = %version, "toolchain catalog: version has no usable artifact");
                skips.versions += 1;
                continue;
            }
            sort_artifacts(&mut artifacts);
            versions.push(ToolVersion::new(
                version.to_owned(),
                series,
                wire_version.lts,
                artifacts,
            ));
        }
        if versions.is_empty() {
            tracing::debug!(tool = %id, "toolchain catalog: tool has no usable version");
            continue;
        }
        sort_versions(&mut versions);
        tools.push(ToolEntry::new(id, versions));
    }

    tools.sort_by_key(ToolEntry::id);
    let catalog = ToolchainCatalog::new(document.generated_at, document.source_url, tools);
    Ok((catalog, skips))
}

fn convert_artifact(
    tool: ToolId,
    wire: &WireArtifact,
    allow_loopback_http: bool,
) -> std::result::Result<Artifact, String> {
    let os = ArtifactOs::from_str(&wire.os).map_err(|e| e.to_string())?;
    let arch = ArtifactArch::from_str(&wire.arch).map_err(|e| e.to_string())?;
    let profile = match wire.profile.as_deref() {
        None | Some("") | Some("null") => None,
        Some(value) => Some(Profile::from_str(value).map_err(|e| e.to_string())?),
    };
    let format = Format::from_str(&wire.format).map_err(|e| e.to_string())?;
    let hash_origin = HashOrigin::from_str(&wire.hash_origin).map_err(|e| e.to_string())?;

    // Profiles are PHP/Linux only; Node and Composer are profile-less, and a
    // Windows PHP build has no profile either.
    let profile = normalize_profile(tool, os, profile);

    Artifact::new_with_policy(
        os,
        arch,
        profile,
        format,
        wire.url.clone(),
        wire.sha256.clone(),
        wire.size_bytes,
        wire.source.clone(),
        hash_origin,
        sorted_extensions(&wire.extensions),
        allow_loopback_http,
    )
    .map_err(|e| e.to_string())
}

fn normalize_profile(tool: ToolId, os: ArtifactOs, profile: Option<Profile>) -> Option<Profile> {
    match tool {
        ToolId::Php if os == ArtifactOs::Linux => profile,
        _ => None,
    }
}

fn sorted_extensions(extensions: &[String]) -> Vec<String> {
    let mut out: Vec<String> = extensions
        .iter()
        .map(|e| e.trim().to_owned())
        .filter(|e| !e.is_empty())
        .collect();
    out.sort();
    out.dedup();
    out
}

fn is_version_tag(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 32
        && value.starts_with(|c: char| c.is_ascii_digit())
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_'))
}

fn default_series(tool: ToolId, version: &str) -> String {
    match tool {
        ToolId::Node => version.split('.').next().unwrap_or(version).to_owned(),
        _ => {
            let mut parts = version.split('.');
            let major = parts.next().unwrap_or(version);
            match parts.next() {
                Some(minor) => format!("{major}.{minor}"),
                None => major.to_owned(),
            }
        }
    }
}

/// Newest first by numeric version comparison, tolerant of non-numeric parts.
fn sort_versions(versions: &mut [ToolVersion]) {
    versions.sort_by(|a, b| compare_versions(b.version(), a.version()));
}

fn sort_artifacts(artifacts: &mut [Artifact]) {
    artifacts.sort_by(|a, b| {
        a.os()
            .as_str()
            .cmp(b.os().as_str())
            .then_with(|| a.arch().as_str().cmp(b.arch().as_str()))
            .then_with(|| profile_key(a.profile()).cmp(&profile_key(b.profile())))
    });
}

fn profile_key(profile: Option<Profile>) -> &'static str {
    profile.map(Profile::as_str).unwrap_or("")
}

/// Compares two dotted version tags numerically, falling back to string compare.
///
/// Pre-release suffixes (`8.4.0-rc1`) sort below their release, matching semver's
/// spirit without pulling a parser into a hot path.
pub fn compare_versions(a: &str, b: &str) -> std::cmp::Ordering {
    let (a_core, a_pre) = split_prerelease(a);
    let (b_core, b_pre) = split_prerelease(b);
    let core = compare_dotted(a_core, b_core);
    if core != std::cmp::Ordering::Equal {
        return core;
    }
    match (a_pre, b_pre) {
        (None, None) => std::cmp::Ordering::Equal,
        (None, Some(_)) => std::cmp::Ordering::Greater,
        (Some(_), None) => std::cmp::Ordering::Less,
        (Some(a), Some(b)) => a.cmp(b),
    }
}

fn split_prerelease(value: &str) -> (&str, Option<&str>) {
    match value.split_once('-') {
        Some((core, pre)) => (core, Some(pre)),
        None => (value, None),
    }
}

fn compare_dotted(a: &str, b: &str) -> std::cmp::Ordering {
    let mut ai = a.split('.');
    let mut bi = b.split('.');
    loop {
        match (ai.next(), bi.next()) {
            (None, None) => return std::cmp::Ordering::Equal,
            (None, Some(other)) => {
                return if is_all_zero(other) {
                    std::cmp::Ordering::Equal
                } else {
                    std::cmp::Ordering::Less
                };
            }
            (Some(other), None) => {
                return if is_all_zero(other) {
                    std::cmp::Ordering::Equal
                } else {
                    std::cmp::Ordering::Greater
                };
            }
            (Some(x), Some(y)) => {
                let ord = match (x.parse::<u64>(), y.parse::<u64>()) {
                    (Ok(x), Ok(y)) => x.cmp(&y),
                    _ => x.cmp(y),
                };
                if ord != std::cmp::Ordering::Equal {
                    return ord;
                }
            }
        }
    }
}

fn is_all_zero(part: &str) -> bool {
    part.parse::<u64>().map(|n| n == 0).unwrap_or(false)
}

